from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, PageBreak, Table, TableStyle

OUT = "/home/aslam/Minor_Project/tree_appendix.pdf"
ss = getSampleStyleSheet()
ss.add(ParagraphStyle(name="X1", parent=ss["Heading1"], fontSize=17, leading=21, textColor=colors.HexColor("#153B5B"), spaceAfter=8))
ss.add(ParagraphStyle(name="X2", parent=ss["Heading2"], fontSize=13, leading=17, textColor=colors.HexColor("#176B78"), spaceAfter=6))
ss.add(ParagraphStyle(name="XB", parent=ss["BodyText"], fontSize=9.3, leading=13.5, spaceAfter=7))
ss.add(ParagraphStyle(name="XC", parent=ss["Code"], fontName="Courier", fontSize=7.8, leading=10.3, backColor=colors.HexColor("#F1F5F7"), borderPadding=7, spaceAfter=8))

def P(x, style="XB"): return Paragraph(x, ss[style])
def T(rows):
    data = [[P(str(x), "XB") for x in r] for r in rows]
    t = Table(data, colWidths=[58*mm, 104*mm], repeatRows=1)
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#176B78")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.5,colors.HexColor("#B6C9D2")),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),5),("BOTTOMPADDING",(0,0),(-1,-1),5)]))
    return t
def footer(c,d):
    c.saveState(); c.setFont("Helvetica",8); c.setFillColor(colors.HexColor("#53636D")); c.drawString(17*mm,8*mm,"Before/After Build Trees and Viva Appendix"); c.drawRightString(193*mm,8*mm,f"Appendix page {d.page}"); c.restoreState()

d = SimpleDocTemplate(OUT,pagesize=A4,leftMargin=17*mm,rightMargin=17*mm,topMargin=16*mm,bottomMargin=18*mm)
s = [P("Appendix: Before-and-After Build Trees", "X1"), P("This appendix shows what existed before each build, what the build added, why each output is included, and common viva questions.")]

s += [P("A. Step 1 — OP-TEE", "X2"), P("BEFORE: optee_os/<br/>├── core/ — secure-kernel source<br/>├── lib/ — secure APIs<br/>├── mk/ — build rules<br/>└── ta/ — TA source<br/><br/>AFTER: optee_os/out/arm/ NEW<br/>├── core/tee.bin — complete Secure World binary<br/>├── core/tee.elf — debug/symbol image<br/>├── core/tee-header_v2.bin — TF-A loading header<br/>├── core/tee-pager_v2.bin — main secure payload<br/>└── export-ta_arm64/ — TA development files", "XC"), T([["Question","Deep answer"],["Why include OP-TEE?","Linux is not trusted for secret keys and final security decisions; OP-TEE provides Secure World execution."],["Why several tee files?","The selected TF-A format uses header/pager/pageable pieces; tee.elf supports debugging."],["Does tee.bin prove runtime?","No. It proves compilation only."]])]

s += [PageBreak(), P("B. Step 2 — U-Boot and TF-A", "X2"), P("U-BOOT BEFORE<br/>u-boot/{arch, board, cmd, configs/rpi_3_defconfig, drivers, Makefile}<br/><br/>U-BOOT AFTER<br/>├── .config — selected RPi3 configuration<br/>├── u-boot — ELF/debug file<br/>├── u-boot.bin — NEW raw BL33 payload<br/>├── System.map — symbols<br/>└── tools/ — boot-image/environment tools<br/><br/>TF-A BEFORE<br/>trusted-firmware-a/{bl1, plat/rpi3, services, Makefile}<br/><br/>TF-A AFTER<br/>trusted-firmware-a/build/rpi3/debug/<br/>├── bl1.bin — early secure firmware<br/>├── fip.bin — BL32 OP-TEE + BL33 U-Boot<br/>└── armstub8.bin — padded BL1 + FIP", "XC"), T([["Question","Deep answer"],["Why both TF-A and U-Boot?","TF-A performs secure initialization/world switching; U-Boot loads Linux, the DTB and arguments."],["Why BL32?","BL32 is TF-A's Secure Payload position used for OP-TEE."],["Why BL33?","BL33 is the non-secure payload used for U-Boot."],["Why no separate FIP copy?","The RPi3 armstub8.bin already includes the FIP after padded BL1."]])]

s += [PageBreak(), P("C. Step 3 — Linux and Device Trees", "X2"), P("BEFORE: linux/<br/>├── arch/arm64/ — ARM64 source/configuration<br/>├── arch/arm64/boot/dts/ — existing DTS source<br/>├── drivers/ — includes TEE drivers<br/>├── fs/ and net/<br/>└── Makefile<br/><br/>AFTER: linux/<br/>├── .config — generated configuration<br/>├── vmlinux + System.map — debug/symbol outputs<br/>├── arch/arm64/boot/Image — NEW ARM64 kernel<br/>├── .../bcm2710-rpi-3-b.dtb — compiled existing DTS<br/>├── .../bcm2710-rpi-3-b-plus.dtb — compiled existing DTS<br/>└── generated .o and .ko files", "XC"), T([["Question","Deep answer"],["Why change Linux config?","To select ARM64/RPi3 support and include CONFIG_TEE plus CONFIG_OPTEE."],["Why DTBs without new hardware?","ARM Linux needs a board description. Existing RPi3 DTS source was compiled; no customization was made."],["Why two DTBs?","The project covers Model B and B+; only the matching physical-board DTB is used."],["Does this prove communication?","No. Board boot and xtest/example success are required."]])]

s += [PageBreak(), P("D. Step 4 — Verification Tree", "X2"), P("BEFORE<br/>Minor_Project/<br/>├── optee_full/ — complete, not formally selected<br/>├── optee_project/ — incomplete laptop copy<br/>├── Step3_Output/<br/>└── loose outputs<br/><br/>AFTER<br/>Minor_Project/<br/>├── optee_full/ — SELECTED authoritative tree<br/>├── Step3_Output/ — preserved<br/>└── Step4_Verification/<br/>    ├── STEP4_COMPLETION.md<br/>    └── verified_artifacts/{optee, tf-a, u-boot, linux}", "XC"), T([["Question","Deep answer"],["Why backup outputs?","Later builds may fail or replace them; backup preserves known successful evidence."],["Why SHA-256?","It fingerprints files to detect corruption or replacement."],["Why compare revisions?","Matching versions improve compatibility and reproducibility."],["Why inspect rpi3.mk?","It defines the supported dependency/packaging flow."]])]

s += [PageBreak(), P("E. Step 5 — Buildroot", "X2"), P("BEFORE<br/>optee_full/<br/>├── buildroot/ — recipes, not a root filesystem<br/>├── optee_client/ — libteec + tee-supplicant source<br/>├── optee_test/ — xtest + test TA source<br/>└── optee_examples/ — host + TA source<br/><br/>CURRENT<br/>├── module_output/ — about 1,713 module-related files<br/>└── out-br/{build, host, per-package, incomplete target}<br/><br/>EXPECTED AFTER SUCCESS<br/>out-br/<br/>├── target/usr/sbin/tee-supplicant<br/>├── target/usr/lib/libteec.so*<br/>├── target/usr/bin/xtest<br/>├── target/usr/bin/optee_example_*<br/>├── target/lib/optee_armtz/*.ta<br/>├── target/lib/modules/&lt;kernel&gt;/*.ko<br/>└── images/rootfs.ext4", "XC"), T([["Question","Purpose/answer"],["Why tee-supplicant?","Normal World RPC help for TA loading and storage-file access."],["Why libteec?","Standard API for opening sessions and invoking TA commands."],["Why xtest?","Standard end-to-end runtime verification."],["Why .ta files?","Security-sensitive code executed by OP-TEE."],["Why matching modules?","Modules must correspond to the exact kernel Image."],["Why rootfs.ext4?","Linux mounts it as / for commands, libraries, services and applications."],["Why missing now?","The configured compiler prefix/path differs from the available AArch64 toolchain."]])]

s += [PageBreak(), P("F. Complete Purpose Chain", "X2")]
s.append(T([["Included item","Why included / what happens if missing"],["OP-TEE","Runs secure validation and TAs; without it there is no Secure World application environment."],["TF-A","Performs secure initialization and world switching; without it the selected BL32 startup path is absent."],["U-Boot","Loads Image, DTB and arguments; without it this flexible Linux-loading stage is absent."],["Linux Image","Runs the Normal World OS and TEE driver."],["DTB","Describes CPU, memory, buses and devices to Linux."],["Kernel modules","Supply matching optional drivers/features."],["Root filesystem","Supplies commands, libraries, services, configuration and applications."],["libteec","Standard client session/command API."],["tee-supplicant","Normal World RPC assistance."],["xtest","Standard proof of the complete runtime path."],["Host application","Ordinary caller that sends permitted requests."],["Trusted Application","Security-sensitive project logic executed in Secure World."]]))

d.build(s,onFirstPage=footer,onLaterPages=footer)
print(OUT)
